describe('908278 - Pasted Ordered List Inherits Parent Element’s OL Tag in Rich Text Editor', () => {
    let rteObj: RichTextEditor;
    let keyBoardEvent: any = {
        preventDefault: () => { },
        type: 'keydown',
        stopPropagation: () => { },
        ctrlKey: false,
        shiftKey: false,
        action: null,
        which: 64,
        key: ''
    };
    beforeAll((done: Function) => {
        const ol = document.createElement('ol');
        const li = document.createElement('li');
        ol.appendChild(li);
        const root: HTMLElement = createElement('div', {className: 'custom'});
        li.appendChild(root);
        document.body.appendChild(ol);
        rteObj = new RichTextEditor({
                pasteCleanupSettings: {
                    prompt: true
                },
                value: ''
        }, root);
        done();
    });
    it('Pasted Ordered List Inherits Parent Element’s OL Tag in Rich Text Editor', (done) => {
        const localElem: string = `<ol><li>HELLO</li><li>HI</li><li>BYE</li></ol>`;
        rteObj.value = '<p><br></p>';
        rteObj.dataBind();
        keyBoardEvent.clipboardData = {
            getData: () => {
                return localElem;
            },
            items: []
        };
        setCursorPoint((rteObj as any).inputElement.firstElementChild, 0);
        rteObj.onPaste(keyBoardEvent);
        setTimeout(() => {
            if (rteObj.pasteCleanupSettings.prompt) {
                let keepFormat: any = document.getElementById(rteObj.getID() + '_pasteCleanupDialog').getElementsByClassName(CLS_RTE_PASTE_KEEP_FORMAT);
                keepFormat[0].click();
                let pasteOK: any = document.getElementById(rteObj.getID() + '_pasteCleanupDialog').getElementsByClassName(CLS_RTE_PASTE_OK);
                pasteOK[0].click();
            }
            let pastedElem: string = (rteObj as any).inputElement.innerHTML;
            let expected: boolean = true;
            let expectedElem: string = `<ol><li>HELLO</li><li>HI</li><li>BYE</li></ol>`;
            if (pastedElem !== expectedElem) {
                expected = false;
            }
            (rteObj as any).inputElement.blur();
            expect(expected).toBe(true);
            done();
        }, 100);
    });
    afterAll((done: DoneFn) => {
        destroy(rteObj);
        done();
    });
});

